class Solution { boolean[] used; public int countArrangement(int n) { used = new boolean[n + 1]; return solve(1, n); } int solve(int position, int n) { if (position > n) { return 1; } int count = 0; for (int num = 1; num <= n; num++) { if (!used[num] && (num % position == 0 || position % num == 0)) { used[num] = true; count += solve(position + 1, n); used[num] = false; } } return count; } }